-- >>> 007_ai.sql
-- AI quota is a count of ai_usage in the last minute and the last hour,
-- per account and for the whole system. Cron deletes rows older than a few hours.
-- ai_slots is the concurrency lease. Take one by deleting expired rows, then
-- inserting if the live count is still under AI_MAX_CONCURRENCY. GET_LOCK
-- around that check is enough. There is no Redis.
-- ai_credentials holds sodium_crypto_secretbox ciphertext. Nonces are 24 bytes.
-- The row wins over env when it is present. Students never select this table.

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
SET time_zone = '+00:00';
SET SESSION sql_mode = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';

CREATE TABLE IF NOT EXISTS ai_usage (
  id CHAR(36) NOT NULL,
  user_id CHAR(36) NOT NULL,
  endpoint VARCHAR(32) NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_ai_usage_user_created (user_id, created_at),
  KEY idx_ai_usage_created (created_at),
  KEY idx_ai_usage_updated (updated_at),
  CONSTRAINT fk_ai_usage_user FOREIGN KEY (user_id) REFERENCES accounts (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS ai_slots (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  account_id CHAR(36) NULL,
  token CHAR(36) NOT NULL,
  acquired_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  expires_at DATETIME(3) NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_ai_slots_token (token),
  KEY idx_ai_slots_expires (expires_at),
  KEY idx_ai_slots_account (account_id),
  CONSTRAINT fk_ai_slots_account FOREIGN KEY (account_id) REFERENCES accounts (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS ai_credentials (
  id VARCHAR(32) NOT NULL,
  provider ENUM('auto', 'gemini', 'openrouter', 'none') NOT NULL DEFAULT 'auto',
  gemini_ciphertext VARBINARY(1024) NULL,
  gemini_nonce BINARY(24) NULL,
  openrouter_ciphertext VARBINARY(1024) NULL,
  openrouter_nonce BINARY(24) NULL,
  openrouter_model VARCHAR(191) NULL,
  configured_at DATETIME(3) NULL,
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS agent_chat_logs (
  id CHAR(36) NOT NULL,
  user_id CHAR(36) NOT NULL,
  session_id VARCHAR(64) NULL,
  provider VARCHAR(32) NOT NULL,
  model VARCHAR(191) NULL,
  settings_snapshot JSON NULL,
  routing JSON NULL,
  request_messages JSON NULL,
  response_parts JSON NULL,
  steps JSON NULL,
  truncated TINYINT(1) NOT NULL DEFAULT 0,
  finish_reason VARCHAR(64) NULL,
  error TEXT NULL,
  duration_ms INT UNSIGNED NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_agent_chat_logs_created (created_at),
  KEY idx_agent_chat_logs_user_created (user_id, created_at),
  KEY idx_agent_chat_logs_session (session_id),
  KEY idx_agent_chat_logs_updated (updated_at),
  CONSTRAINT fk_agent_chat_logs_user FOREIGN KEY (user_id) REFERENCES accounts (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- >>> 008_nfc.sql
-- NFC tags and found reports. Public resolve must not select contacts.
-- tag_uid is unique when it is set. Store NULL when there is no hardware id,
-- not an empty string. MariaDB treats each NULL as distinct.

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
SET time_zone = '+00:00';
SET SESSION sql_mode = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';

CREATE TABLE IF NOT EXISTS nfc_tags (
  id VARCHAR(32) NOT NULL,
  tag_uid VARCHAR(64) NULL,
  owner_id CHAR(36) NOT NULL,
  item_name VARCHAR(255) NOT NULL,
  category VARCHAR(64) NOT NULL,
  description TEXT NULL,
  contacts JSON NOT NULL DEFAULT ('[]'),
  status ENUM('active', 'lost', 'returned', 'disabled') NOT NULL DEFAULT 'active',
  read_only_locked TINYINT(1) NOT NULL DEFAULT 0,
  lost_item_id CHAR(36) NULL,
  last_found_report_id CHAR(36) NULL,
  ndef_written_at DATETIME(3) NULL,
  registered_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_nfc_tags_tag_uid (tag_uid),
  KEY idx_nfc_tags_owner_registered (owner_id, registered_at),
  KEY idx_nfc_tags_lost_item (lost_item_id),
  KEY idx_nfc_tags_updated (updated_at),
  CONSTRAINT fk_nfc_tags_owner FOREIGN KEY (owner_id) REFERENCES accounts (id) ON DELETE CASCADE,
  CONSTRAINT fk_nfc_tags_lost_item FOREIGN KEY (lost_item_id) REFERENCES lost_items (id) ON DELETE SET NULL,
  CONSTRAINT chk_nfc_tags_uid CHECK (tag_uid IS NULL OR CHAR_LENGTH(tag_uid) > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS nfc_found_reports (
  id CHAR(36) NOT NULL,
  tag_id VARCHAR(32) NOT NULL,
  owner_id CHAR(36) NOT NULL,
  finder_user_id CHAR(36) NOT NULL,
  finder_message TEXT NOT NULL,
  location_found VARCHAR(255) NULL,
  location_coords JSON NULL,
  finder_contacts JSON NULL,
  status ENUM('pending', 'viewed', 'resolved') NOT NULL DEFAULT 'pending',
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_nfc_found_reports_owner_created (owner_id, created_at),
  KEY idx_nfc_found_reports_tag_created (tag_id, created_at),
  KEY idx_nfc_found_reports_finder_created (finder_user_id, created_at),
  KEY idx_nfc_found_reports_updated (updated_at),
  CONSTRAINT fk_nfc_found_reports_tag FOREIGN KEY (tag_id) REFERENCES nfc_tags (id) ON DELETE CASCADE,
  CONSTRAINT fk_nfc_found_reports_owner FOREIGN KEY (owner_id) REFERENCES accounts (id) ON DELETE CASCADE,
  CONSTRAINT fk_nfc_found_reports_finder FOREIGN KEY (finder_user_id) REFERENCES accounts (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET @fk_exists := (
  SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS
  WHERE CONSTRAINT_SCHEMA = DATABASE()
    AND TABLE_NAME = 'nfc_tags'
    AND CONSTRAINT_NAME = 'fk_nfc_tags_last_report'
    AND CONSTRAINT_TYPE = 'FOREIGN KEY'
);
SET @fk_sql := IF(
  @fk_exists = 0,
  'ALTER TABLE nfc_tags ADD CONSTRAINT fk_nfc_tags_last_report FOREIGN KEY (last_found_report_id) REFERENCES nfc_found_reports (id) ON DELETE SET NULL',
  'SET @fk_noop := 1'
);
PREPARE foundu_stmt FROM @fk_sql;
EXECUTE foundu_stmt;
DEALLOCATE PREPARE foundu_stmt;

-- >>> 009_cms.sql
-- Help pages and articles. Public reads of articles are status = published.
-- Drafts are admin-only. Help rows are readable, including audience = admin,
-- which matches the old policy. Tag search is JSON_CONTAINS. The table is
-- small, so there is no extra tag index. MariaDB has no GIN.

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
SET time_zone = '+00:00';
SET SESSION sql_mode = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';

CREATE TABLE IF NOT EXISTS help_pages (
  slug VARCHAR(128) NOT NULL,
  title VARCHAR(255) NOT NULL,
  description TEXT NULL,
  intro TEXT NULL,
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS help_sections (
  id CHAR(36) NOT NULL,
  page_slug VARCHAR(128) NOT NULL,
  section_type ENUM('step', 'note', 'faq') NOT NULL DEFAULT 'step',
  audience ENUM('all', 'student', 'admin') NOT NULL DEFAULT 'all',
  title VARCHAR(255) NOT NULL,
  body MEDIUMTEXT NOT NULL,
  image_url VARCHAR(2048) NULL,
  sort_order INT NOT NULL DEFAULT 0,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_help_sections_page_sort (page_slug, sort_order),
  KEY idx_help_sections_updated (updated_at),
  CONSTRAINT fk_help_sections_page FOREIGN KEY (page_slug) REFERENCES help_pages (slug) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS articles (
  id CHAR(36) NOT NULL,
  slug VARCHAR(191) NOT NULL,
  section ENUM('blog', 'help') NOT NULL DEFAULT 'blog',
  status ENUM('draft', 'published') NOT NULL DEFAULT 'draft',
  title VARCHAR(255) NOT NULL,
  excerpt TEXT NULL,
  cover_image_url VARCHAR(2048) NULL,
  author_name VARCHAR(255) NULL,
  tags JSON NOT NULL DEFAULT ('[]'),
  content_json JSON NOT NULL DEFAULT ('{"type":"doc","content":[]}'),
  published_at DATETIME(3) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_articles_slug (slug),
  KEY idx_articles_section_status_published (section, status, published_at),
  KEY idx_articles_updated (updated_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- >>> 010_change_feed.sql
-- One row per table that GET /api/changes may name.
-- updated_at moves on insert, update, and delete. MAX(updated_at) on the
-- source table misses deletes, so the poll reads this table.
-- Platform tables (sessions, rate_limits, login_attempts, ai_slots,
-- ai_credentials, schema_migrations) are not in the feed.

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
SET time_zone = '+00:00';
SET SESSION sql_mode = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';

CREATE TABLE IF NOT EXISTS change_feed (
  table_name VARCHAR(64) NOT NULL,
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (table_name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

