-- >>> 011_cron_lock.sql
-- One row so two DirectAdmin cron runs cannot overlap.
-- The runner inserts its own id. If the row is still locked, the second
-- process exits immediately. A crashed run leaves the row until locked_until,
-- then the next run takes it. This is not a visitor-facing table.

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
SET time_zone = '+00:00';
SET SESSION sql_mode = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';

CREATE TABLE IF NOT EXISTS cron_lock (
  name VARCHAR(32) NOT NULL,
  owner CHAR(36) NOT NULL,
  locked_until DATETIME(3) NOT NULL,
  PRIMARY KEY (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- >>> 012_list_indexes.sql
-- Keyset lists walk (created_at, id). Status indexes do not cover an
-- unfiltered admin list, and accounts had no created_at index at all.
-- MariaDB 10.11 accepts ADD INDEX IF NOT EXISTS.

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
SET time_zone = '+00:00';
SET SESSION sql_mode = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';

ALTER TABLE lost_items ADD INDEX IF NOT EXISTS idx_lost_items_created_id (created_at, id);
ALTER TABLE found_items ADD INDEX IF NOT EXISTS idx_found_items_created_id (created_at, id);
ALTER TABLE accounts ADD INDEX IF NOT EXISTS idx_accounts_created_id (created_at, id);
ALTER TABLE match_dismissals ADD INDEX IF NOT EXISTS idx_match_dismissals_created_id (created_at, id);

-- >>> 030_geocode_cache.sql
-- Nominatim answers are cached here so the admin place search does not
-- hit the upstream on every keypress, and so a short outage still has
-- yesterday's result. The query is not a secret. Cron drops old rows.

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
SET time_zone = '+00:00';
SET SESSION sql_mode = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';

CREATE TABLE IF NOT EXISTS geocode_cache (
  query_hash CHAR(64) NOT NULL,
  query_text VARCHAR(200) NOT NULL,
  payload JSON NOT NULL,
  fetched_at DATETIME(3) NOT NULL,
  PRIMARY KEY (query_hash),
  KEY idx_geocode_cache_fetched (fetched_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- >>> 040_storage_objects.sql
-- Objects we have agreed to let a browser upload.
-- The key also carries the account id (avatars/{accountId}/…).
-- This row is the copy delete checks. Both have to match.
-- Not in change_feed: the browser does not poll it.
-- Deleting the account removes the row. The R2 object is a separate delete.

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
SET time_zone = '+00:00';
SET SESSION sql_mode = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';

CREATE TABLE IF NOT EXISTS storage_objects (
  object_key VARCHAR(512) NOT NULL,
  account_id CHAR(36) NOT NULL,
  purpose ENUM('avatar', 'found', 'blog', 'help', 'branding') NOT NULL,
  content_type VARCHAR(64) NOT NULL,
  bytes INT UNSIGNED NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (object_key),
  KEY idx_storage_objects_account (account_id, created_at),
  CONSTRAINT fk_storage_objects_account FOREIGN KEY (account_id) REFERENCES accounts (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
